/**
 * Every failure the core reports, to Rust callers and through UniFFI.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Word number `index` (from 0) is not a BIP39 English word.
     */
    case UnknownWord(
        /**
         * Position of the word, from 0.
         */index: UInt32
    )
    /**
     * The words are all on the list but their BIP39 checksum fails.
     */
    case Checksum
    /**
     * Not 24 words.
     */
    case Count
    /**
     * Not a sealctl pairing link or code.
     */
    case BadLink
    /**
     * A pairing code past its expiry, or a request outside the 10-minute window.
     */
    case Expired
    /**
     * The other side speaks a newer protocol version.
     */
    case NewerVersion
    /**
     * A pairing or move proof that does not check out.
     */
    case BadProof
    /**
     * An Ed25519 signature that does not verify.
     */
    case BadSignature
    /**
     * A sealed string or blob that cannot be decoded or opened, or is too long.
     */
    case BadSealed
    /**
     * This request was already answered.
     */
    case Replay
    /**
     * A key purpose or object id outside the allowed set.
     */
    case BadLabel
    /**
     * A plan that breaks the plan rules or does not match its hash.
     */
    case BadPlan
    /**
     * Bytes or text that are not a valid key (wrong length or encoding).
     */
    case BadKey
    /**
     * The answer does not fit the request's kind (for example keys for a `report`).
     */
    case WrongDecision
    /**
     * The body does not fit in its sealed form (4,096 characters, state blob 1 MiB).
     */
    case TooLarge
    /**
     * A failure that should not happen (the OS random source, an encoder).
     */
    case Internal

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownWord(
            index: try FfiConverterUInt32.read(from: &buf)
            )
        case 2: return .Checksum
        case 3: return .Count
        case 4: return .BadLink
        case 5: return .Expired
        case 6: return .NewerVersion
        case 7: return .BadProof
        case 8: return .BadSignature
        case 9: return .BadSealed
        case 10: return .Replay
        case 11: return .BadLabel
        case 12: return .BadPlan
        case 13: return .BadKey
        case 14: return .WrongDecision
        case 15: return .TooLarge
        case 16: return .Internal

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownWord(index):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(index, into: &buf)
            
        
        case .Checksum:
            writeInt(&buf, Int32(2))
        
        
        case .Count:
            writeInt(&buf, Int32(3))
        
        
        case .BadLink:
            writeInt(&buf, Int32(4))
        
        
        case .Expired:
            writeInt(&buf, Int32(5))
        
        
        case .NewerVersion:
            writeInt(&buf, Int32(6))
        
        
        case .BadProof:
            writeInt(&buf, Int32(7))
        
        
        case .BadSignature:
            writeInt(&buf, Int32(8))
        
        
        case .BadSealed:
            writeInt(&buf, Int32(9))
        
        
        case .Replay:
            writeInt(&buf, Int32(10))
        
        
        case .BadLabel:
            writeInt(&buf, Int32(11))
        
        
        case .BadPlan:
            writeInt(&buf, Int32(12))
        
        
        case .BadKey:
            writeInt(&buf, Int32(13))
        
        
        case .WrongDecision:
            writeInt(&buf, Int32(14))
        
        
        case .TooLarge:
            writeInt(&buf, Int32(15))
        
        
        case .Internal:
            writeInt(&buf, Int32(16))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lift(_ buf: RustBuffer) throws -> CoreError {
    return try FfiConverterTypeCoreError.lift(buf)
}

