/**
 * What the person (or the levels of asking) decided.
 */

public enum Decision: Equatable, Hashable {
    
    /**
     * Declined (`declined`).
     */
    case deny
    /**
     * Refused for a reason.
     */
    case refuse(
        /**
         * The reason.
         */err: RefuseReason
    )
    /**
     * Keys and uses for the command that asked, then wiped (`grant: once`).
     */
    case once(
        /**
         * Where the phone is.
         */place: Place
    )
    /**
     * Kept until the session locks (`grant: session`).
     */
    case session(
        /**
         * Where the phone is.
         */place: Place
    )
    /**
     * `Session`, and the agent uses are remembered (`remember: true`).
     */
    case remember(
        /**
         * Where the phone is.
         */place: Place
    )
    /**
     * `unseal`: sign the plan and hand out keys named by it (`grant: plan`).
     */
    case plan(
        /**
         * Where the phone is.
         */place: Place, 
        /**
         * Approval time, or one hour later away from a trusted place; Unix ms.
         */notBefore: UInt64
    )





}

#if compiler(>=6)
extension Decision: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDecision: FfiConverterRustBuffer {
    typealias SwiftType = Decision

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Decision {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .deny
        
        case 2: return .refuse(err: try FfiConverterTypeRefuseReason.read(from: &buf)
        )
        
        case 3: return .once(place: try FfiConverterTypePlace.read(from: &buf)
        )
        
        case 4: return .session(place: try FfiConverterTypePlace.read(from: &buf)
        )
        
        case 5: return .remember(place: try FfiConverterTypePlace.read(from: &buf)
        )
        
        case 6: return .plan(place: try FfiConverterTypePlace.read(from: &buf), notBefore: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Decision, into buf: inout [UInt8]) {
        switch value {
        
        
        case .deny:
            writeInt(&buf, Int32(1))
        
        
        case let .refuse(err):
            writeInt(&buf, Int32(2))
            FfiConverterTypeRefuseReason.write(err, into: &buf)
            
        
        case let .once(place):
            writeInt(&buf, Int32(3))
            FfiConverterTypePlace.write(place, into: &buf)
            
        
        case let .session(place):
            writeInt(&buf, Int32(4))
            FfiConverterTypePlace.write(place, into: &buf)
            
        
        case let .remember(place):
            writeInt(&buf, Int32(5))
            FfiConverterTypePlace.write(place, into: &buf)
            
        
        case let .plan(place,notBefore):
            writeInt(&buf, Int32(6))
            FfiConverterTypePlace.write(place, into: &buf)
            FfiConverterUInt64.write(notBefore, into: &buf)
            
        }
    }
}


