/**
 * The kinds of machine message (`type`).
 */

public enum MessageKind: Equatable, Hashable {
    
    /**
     * Lock the session.
     */
    case lock(
        /**
         * `phone`, `place` or `words`.
         */reason: String
    )
    /**
     * This machine's remembered answers.
     */
    case answers(
        /**
         * At most 40 per message.
         */answers: [Answer], 
        /**
         * Another `answers` message follows.
         */more: Bool
    )
    /**
     * The status `seq` the phone stored.
     */
    case ack(
        /**
         * The `seq`.
         */ack: UInt64
    )
    /**
     * A level 3 action, for the machine to show.
     */
    case notice(
        /**
         * What happened.
         */notice: Notice
    )





}

#if compiler(>=6)
extension MessageKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMessageKind: FfiConverterRustBuffer {
    typealias SwiftType = MessageKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MessageKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .lock(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .answers(answers: try FfiConverterSequenceTypeAnswer.read(from: &buf), more: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .ack(ack: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .notice(notice: try FfiConverterTypeNotice.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MessageKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .lock(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .answers(answers,more):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceTypeAnswer.write(answers, into: &buf)
            FfiConverterBool.write(more, into: &buf)
            
        
        case let .ack(ack):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(ack, into: &buf)
            
        
        case let .notice(notice):
            writeInt(&buf, Int32(4))
            FfiConverterTypeNotice.write(notice, into: &buf)
            
        }
    }
}


